   114→  // compute_fork_digest
   115→  public Bytes4 computeForkDigest(final Bytes32 genesisValidatorsRoot, final UInt64 epoch) {
   116→    final Bytes4 forkVersion = computeForkVersion(epoch);
   117→    final Bytes32 baseDigest = computeForkDataRoot(forkVersion, genesisValidatorsRoot);
   118→    final BlobParameters blobParameters = getBlobParameters(epoch);
   119→    // Bitmask digest with hash of blob parameters
   120→    return new Bytes4(baseDigest.xor(blobParameters.hash()).slice(0, 4));
   121→  }
