   226→            .reduce(UInt64.ZERO, UInt64::plus);
   227→    final UInt64 count =
   228→        totalNodeBalance.dividedBy(specConfigFulu.getBalancePerAdditionalCustodyGroup());
   229→    return count
   230→        .max(specConfigFulu.getValidatorCustodyRequirement())
   231→        .min(specConfigFulu.getNumberOfCustodyGroups());
