   234→  public boolean verifyDataColumnSidecar(final DataColumnSidecar dataColumnSidecar) {
   235→    final int numberOfColumns = specConfigFulu.getNumberOfColumns();
   236→
   237→    if (!dataColumnSidecar.getIndex().isLessThan(numberOfColumns)) {
   238→      LOG.trace(
   239→          "DataColumnSidecar has invalid index {}. Should be less than {}",
   240→          dataColumnSidecar.getIndex(),
   241→          numberOfColumns);
   242→      return false;
   243→    }
   244→    if (dataColumnSidecar.getSszKZGCommitments().isEmpty()) {
   245→      LOG.trace("DataColumnSidecar has no kzg commitments");
   246→      return false;
   247→    }
   248→    if (dataColumnSidecar.getDataColumn().size()
   249→        != dataColumnSidecar.getSszKZGCommitments().size()) {
   250→      LOG.trace(
   251→          "DataColumnSidecar has unequal data column ({}) and kzg commitments ({}) sizes",
   252→          dataColumnSidecar.getDataColumn().size(),
   253→          dataColumnSidecar.getSszKZGCommitments().size());
   254→      return false;
   255→    }
   256→    if (dataColumnSidecar.getDataColumn().size() != dataColumnSidecar.getSszKZGProofs().size()) {
   257→      LOG.trace(
   258→          "DataColumnSidecar has unequal data column ({}) and kzg proofs ({}) sizes",
   259→          dataColumnSidecar.getDataColumn().size(),
   260→          dataColumnSidecar.getSszKZGProofs().size());
   261→      return false;
   262→    }
   263→    return true;
   264→  }
