   288→    final List<KZGCellWithColumnId> cellWithIds =
   289→        dataColumnSidecars.stream()
   290→            .flatMap(
   291→                dataColumnSidecar ->
   292→                    IntStream.range(0, dataColumnSidecar.getDataColumn().size())
   293→                        .mapToObj(
