   492→  public List<DataColumnSidecar> reconstructAllDataColumnSidecars(
   493→      final Collection<DataColumnSidecar> existingSidecars, final KZG kzg) {
   494→    if (existingSidecars.size() < (specConfigFulu.getNumberOfColumns() / 2)) {
   495→      final Optional<DataColumnSidecar> maybeSidecar = existingSidecars.stream().findAny();
   496→      throw new IllegalArgumentException(
   497→          String.format(
   498→              "Number of sidecars must be greater than or equal to the half of column count, slot: %s; columns: found %s, needed at least %d",
   499→              maybeSidecar.isPresent() ? maybeSidecar.get().getSlot().toString() : "unknown",
   500→              existingSidecars.size(),
   501→              specConfigFulu.getNumberOfColumns() / 2));
   502→    }
   503→    final List<List<MatrixEntry>> columnBlobEntries =
   504→        existingSidecars.stream()
   505→            .map(
   506→                sidecar ->
   507→                    IntStream.range(0, sidecar.getDataColumn().size())
   508→                        .mapToObj(
   509→                            rowIndex ->
   510→                                schemaDefinitionsFulu
   511→                                    .getMatrixEntrySchema()
   512→                                    .create(
   513→                                        sidecar.getDataColumn().get(rowIndex),
   514→                                        sidecar.getSszKZGProofs().get(rowIndex).getKZGProof(),
   515→                                        sidecar.getIndex(),
   516→                                        UInt64.valueOf(rowIndex)))
   517→                        .toList())
   518→            .toList();
   519→    final List<List<MatrixEntry>> blobColumnEntries = transpose(columnBlobEntries);
   520→    final List<List<MatrixEntry>> extendedMatrix = recoverMatrix(blobColumnEntries, kzg);
   521→    final DataColumnSidecar anyExistingSidecar =
   522→        existingSidecars.stream().findFirst().orElseThrow();
   523→    final SignedBeaconBlockHeader signedBeaconBlockHeader =
   524→        anyExistingSidecar.getSignedBeaconBlockHeader();
   525→    return constructDataColumnSidecars(
   526→        signedBeaconBlockHeader,
   527→        anyExistingSidecar.getSszKZGCommitments(),
   528→        anyExistingSidecar.getKzgCommitmentsInclusionProof().asListUnboxed(),
   529→        extendedMatrix);
   530→  }
   531→
   532→  /**
   533→   * Return the recovered extended matrix.
   534→   *
   535→   * <p>This helper demonstrates how to apply ``recover_cells_and_kzg_proofs``.
   536→   *
   537→   * <p>The data structure for storing cells is implementation-dependent.
   538→   */
   539→  public List<List<MatrixEntry>> recoverMatrix(
   540→      final List<List<MatrixEntry>> partialMatrix, final KZG kzg) {
   541→    return IntStream.range(0, partialMatrix.size())
   542→        .parallel()
   543→        .mapToObj(
   544→            blobIndex -> {
   545→              final List<KZGCellWithColumnId> cellWithColumnIds =
   546→                  partialMatrix.get(blobIndex).stream()
   547→                      .filter(entry -> entry.getRowIndex().intValue() == blobIndex)
   548→                      .map(
   549→                          entry ->
   550→                              new KZGCellWithColumnId(
   551→                                  new KZGCell(entry.getCell().getBytes()),
   552→                                  new KZGCellID(entry.getColumnIndex())))
   553→                      .toList();
   554→              final List<KZGCellAndProof> kzgCellAndProofs =
   555→                  kzg.recoverCellsAndProofs(cellWithColumnIds);
   556→              return IntStream.range(0, kzgCellAndProofs.size())
   557→                  .mapToObj(
   558→                      kzgCellAndProofIndex ->
   559→                          schemaDefinitionsFulu
   560→                              .getMatrixEntrySchema()
   561→                              .create(
   562→                                  kzgCellAndProofs.get(kzgCellAndProofIndex).cell(),
   563→                                  kzgCellAndProofs.get(kzgCellAndProofIndex).proof(),
   564→                                  kzgCellAndProofIndex,
   565→                                  blobIndex))
   566→                  .toList();
   567→            })
   568→        .toList();
   569→  }
   570→
   571→  public int getSamplingGroupCount(final int custodyRequirement) {
   572→    return Math.max(custodyRequirement, specConfigFulu.getSamplesPerSlot());
   573→  }
   574→
   575→  private static <T> List<List<T>> transpose(final List<List<T>> matrix) {
   576→    final int rowCount = matrix.size();
   577→    final int colCount = matrix.getFirst().size();
   578→    final List<List<T>> ret =
   579→        Stream.generate(() -> (List<T>) new ArrayList<T>(rowCount)).limit(colCount).toList();
   580→
   581→    for (int row = 0; row < rowCount; row++) {
   582→      if (matrix.get(row).size() != colCount) {
   583→        throw new IllegalArgumentException("Different number columns in the matrix");
   584→      }
   585→      for (int col = 0; col < colCount; col++) {
   586→        final T val = matrix.get(row).get(col);
   587→        ret.get(col).add(row, val);
   588→      }
   589→    }
   590→    return ret;
   591→  }
